'use strict';
const spheres = [
 {name:'Смысл и интерес',short:'Смысл',hint:'Мне интересны мои задачи, и я понимаю, ради чего работаю',why:'Если работа даёт мало смысла, смена должности сама по себе может не изменить опыт. Полезно выяснить, что именно вам хочется делать и для кого.',step:'Выпишите три рабочих эпизода, в которых вам было интересно, и три, которые казались пустыми. Найдите одну общую черту в каждой группе.',question:'Если убрать ожидания других, ради чего я сам хочу продолжать эту работу?'},
 {name:'Доход и вознаграждение',short:'Доход',hint:'Оплата моего труда соответствует моим потребностям и вкладу',why:'Удовлетворённость оплатой влияет на ощущение справедливости и свободу карьерных решений. Здесь важно различать необходимый доход и признание вклада.',step:'Назовите желаемые условия оплаты и запишите три конкретных результата вашей работы. Подготовьте один вопрос о возможностях пересмотра вознаграждения.',question:'Что для меня означает достойная оплата: безопасность, свободу или подтверждение моей ценности?'},
 {name:'Нагрузка и ресурс',short:'Нагрузка',hint:'Рабочий ритм посилен, остаются силы и возможность отключаться',why:'Если ритм работы вам не подходит, дополнительное обучение или повышение могут увеличить нагрузку. Сначала полезно проверить объём задач и границы.',step:'За одну рабочую неделю отметьте задачи, которые забирают больше всего сил. Выберите одну, по которой можно обсудить срок, объём или распределение ответственности.',question:'Какую цену я плачу за свой нынешний рабочий ритм и какую больше не готов платить?'},
 {name:'Команда и отношения',short:'Команда',hint:'С коллегами и руководителем можно обсуждать сложности и получать поддержку',why:'Отношения на работе могут помогать реализовать сильные стороны или затруднять это. Важно отделить неудобный формат общения от самого профессионального направления.',step:'Вспомните одну трудную рабочую ситуацию. Разделите факты, вашу интерпретацию и желаемую договорённость. Подготовьте конкретную просьбу для разговора.',question:'Что я пока не говорю на работе и чего опасаюсь, если скажу это прямо?'},
 {name:'Признание и влияние',short:'Влияние',hint:'Мой вклад замечают, я могу влиять на решения в своей зоне ответственности',why:'Признание и влияние — разные вещи. Можно получать похвалу, но не иметь права принимать решения. Уточните, чего вам не хватает.',step:'Опишите один вклад, который остаётся незаметным, и одно решение, на которое хочется влиять. Выберите, с кем обсудить это на конкретном примере.',question:'Где я жду разрешения проявить себя и какой части влияния могу добиваться сам?'},
 {name:'Развитие и мастерство',short:'Развитие',hint:'Я использую сильные стороны и развиваю нужные мне навыки',why:'Рост полезен, когда ведёт к вашей цели. Новые курсы без возможности применять знания могут не менять карьерную ситуацию.',step:'Выберите один нужный навык и небольшую рабочую задачу, где его можно попробовать за 30 минут. Определите, у кого попросить обратную связь.',question:'Я учусь ради своего следующего шага или чтобы отложить решение, которое уже назрело?'},
 {name:'Свобода и условия',short:'Свобода',hint:'Мне подходят формат, график и степень самостоятельности в работе',why:'Иногда неудовлетворённость связана с условиями, а не с профессией. Проверка формата и самостоятельности поможет не принимать слишком широкое решение.',step:'Составьте два списка: условия, которые вам необходимы, и те, о которых можно договориться. Выберите одно изменение для обсуждения или небольшого эксперимента.',question:'Какие условия работы я считаю неизменными, хотя ещё не проверял возможность договориться?'},
 {name:'Направление и перспективы',short:'Перспективы',hint:'Я понимаю, куда хочу двигаться и какие возможности есть впереди',why:'Ясность направления помогает выбирать задачи, обучение и предложения. Для начала достаточно проверяемой гипотезы, а не окончательного плана на годы.',step:'Сформулируйте два возможных направления на ближайший год. Для каждого найдите один разговор или небольшую задачу, которые помогут проверить интерес.',question:'Если через год всё останется как сейчас, чему я буду рад, а о чём пожалею?'}
];

function describeCurve(v){
 const low=i=>v[i]<=4,high=i=>v[i]>=7;
 const patterns=[];
 const add=(condition,title,text,question)=>{if(condition)patterns.push({title,text,question});};
 add(high(1)&&low(0),'Доход есть, интереса мало','Оплата устраивает больше, чем содержание работы. Стоит исследовать, какие задачи вернут интерес и что важно сохранить в доходе; из этих оценок не следует необходимость увольняться.','Что удерживает меня в этой работе кроме денег — и какой интерес я готов попробовать вернуть?');
 add(high(0)&&low(2),'Интересная работа с трудным ритмом','Смысл работы оценён высоко, а посильность нагрузки — низко. Возможно, первый предмет изменений — объём и границы работы. Это гипотеза для проверки на конкретной неделе.','Не стала ли увлечённость причиной соглашаться на большее, чем мне подходит?');
 add(high(5)&&low(7),'Развитие без ясного направления','Развитие навыков устраивает, но перспектива пока неясна. Полезно связать обучение с конкретной ролью или задачей, прежде чем выбирать следующую программу.','Куда ведут мои новые навыки, если я перестану оценивать рост количеством обучения?');
 add(high(5)&&low(4),'Мастерство опережает влияние','Развитие оценено выше признания и влияния. Исследуйте, виден ли ваш вклад и есть ли пространство для применения навыков. Причина может быть в разных условиях, а не в вашей компетентности.','Как я показываю свой вклад и о каких полномочиях ещё не просил?');
 add(high(3)&&low(0),'Хорошая команда, мало смысла','Отношения с командой устраивают больше содержания работы. Можно проверить другие задачи внутри знакомой среды и уточнить, насколько именно окружение удерживает вас.','Если бы эта команда осталась, а задачи можно было выбрать заново, чем бы я хотел заниматься?');
 add(high(0)&&low(1),'Смысл есть, вознаграждение не устраивает','Интерес к работе сочетается с низкой оценкой оплаты. Уточните желаемые условия и возможности обсуждения вклада, не обесценивая важный для вас смысл.','Не использую ли я любовь к делу как причину не обсуждать свои условия?');
 add(high(7)&&low(5),'Направление яснее, чем путь развития','Перспективы оценены высоко, но развитие не устраивает. Проверьте, какой навык или опыт нужен для следующего шага и где его можно получить на практике.','Какой один опыт приблизит меня к выбранной роли больше, чем ещё один общий курс?');
 add(low(6)&&low(2),'Условия и нагрузка требуют внимания','Самостоятельность и условия вместе с посильностью нагрузки получили низкие оценки. Уточните, какие договорённости можно пересмотреть и какие требования для вас принципиальны.','Какую границу в работе мне важно обозначить, даже если я пока не знаю всей дальнейшей траектории?');
 add(high(4)&&low(3),'Влияние есть, отношения сложнее','Вклад и влияние оценены высоко, а отношения в команде — низко. Исследуйте конкретные взаимодействия, где нужны ясные договорённости или поддержка.','Какой разговор я откладываю и что хочу изменить в нём, кроме поведения другого человека?');
 const min=Math.min(...v),max=Math.max(...v);const sorted=v.map((n,i)=>({n,i})).sort((a,b)=>a.n-b.n||a.i-b.i);
 let fallback;
 if(max<=4)fallback={title:'Много сфер одновременно требуют внимания',text:'Все оценки сейчас не выше 4. Это не вывод о вашей профессии или причинах состояния. Сначала выберите одну посильную область изменений и уточните, что связано с задачами, условиями и текущим этапом карьеры.',question:'Что в нынешней работе труднее всего переносить и что уже сейчас может немного облегчить эту часть?'};
 else if(min>=7)fallback={title:'Есть несколько устойчивых карьерных опор',text:'Все оценки сейчас не ниже 7. Можно исследовать следующий этап роста или сохранить то, что подходит. Высокие оценки не обязывают вас повышать планку.',question:'Чего мне хочется дальше, если я не обязан ни доказывать успех, ни постоянно расти?'};
 else if(max-min<=2)fallback={title:'Ровная картина — проверьте свои ожидания',text:'Оценки близки друг к другу. Важнее не форма, а то, подходят ли вам эти уровни. Посмотрите, какая из важных для вас сторон работы устраивает меньше остальных.',question:'Я называю это нормальным, потому что мне подходит — или потому что привык не ждать другого?'};
 else if(v.filter(n=>n<=4).length===1)fallback={title:'Одна область выделяется на фоне остальных',text:`Низкая оценка выделяет сферу «${spheres[sorted[0].i].name}». Проверьте, какие конкретные эпизоды стоят за ней и как соседние сферы могут помочь с небольшим изменением.`,question:'Если улучшить только эту часть работы, насколько изменится моё отношение к карьере целиком?'};
 else fallback={title:'Неравномерная карьерная картина',text:`Разброс оценок — ${max-min} баллов. Самая низкая оценка у сферы «${spheres[sorted[0].i].name}», одна из самых высоких — «${spheres[sorted[7].i].name}». Исследуйте, поддерживает ли сильная сторона слабую или помогает долго не замечать неудовлетворённость.`,question:'Какую неудовлетворённость я компенсирую сильной стороной работы и устраивает ли меня такой обмен?'};
 const primary=max<=4||min>=7?fallback:patterns[0]||fallback;
 return {title:primary.title,text:primary.text,question:primary.question,evidence:'Ваши оценки: '+spheres.map((s,i)=>`${s.name} — ${v[i]}/10`).join('; ')+'. Это гипотезы для размышления, а не объяснение причин.'};
}
const $=id=>document.getElementById(id);

const fresh=()=>({scores:Array(8).fill(null),importance:Array(8).fill(2)});
let state=fresh(),current=0,report=null,demo=false,analyticsExample=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function trackGoal(name,once=false){window.careerAnalytics?.goal(name,once);}
function trackStudyStart(){if(!analyticsExample)trackGoal('study_start',true);}
function motion(){return matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth';}
function scrollToSection(id){$(id).focus({preventScroll:true});$(id).scrollIntoView({behavior:motion(),block:'start'});}
function point(i,r){const a=i*Math.PI/4-Math.PI/2;return [220+Math.cos(a)*r,220+Math.sin(a)*r];}
function polygon(v){return v.map((n,i)=>point(i,(n??0)*13).join(',')).join(' ');}
function draw(data=state){let html='';for(let j=2;j<=10;j+=2)html+=`<circle cx="220" cy="220" r="${j*13}" fill="none" stroke="#d8ccc2" stroke-width=".8"/>`;spheres.forEach((s,i)=>{const [x,y]=point(i,130),[tx,ty]=point(i,170);html+=`<line x1="220" y1="220" x2="${x}" y2="${y}" stroke="#e1d5ca" stroke-width=".6"/><circle cx="${x}" cy="${y}" r="2.5" fill="#252525"/><text x="${tx}" y="${ty}" text-anchor="middle" dominant-baseline="middle" fill="#292929" font-family="system-ui" font-size="11">${esc(s.short)}</text>`;});if(data.scores.some(v=>v!==null))html+=`<polygon points="${polygon(data.importance.map((v,i)=>data.scores[i]===null?null:v*3))}" fill="none" stroke="#7b9080" stroke-width="1.3" stroke-dasharray="4 5"/><polygon points="${polygon(data.scores)}" fill="#800e20" fill-opacity=".22" stroke="#800e20" stroke-width="1.8"/>`;data.scores.forEach((v,i)=>{if(v!==null){const [x,y]=point(i,v*13);html+=`<circle cx="${x}" cy="${y}" r="4" fill="#800e20"/>`;}});$('wheel').innerHTML=html;$('wheel').setAttribute('aria-label','Карьерное колесо. '+spheres.map((s,i)=>`${s.name}: ${data.scores[i]??'не оценено'} из 10, важность ${data.importance[i]} из 3`).join('; '));}
function renderStep(){const s=spheres[current];$('sphere-name').textContent=s.name;$('sphere-hint').textContent=s.hint;$('score').value=state.scores[current]??5;$('score-output').textContent=state.scores[current]===null?'— / 10':state.scores[current]+' / 10';$('score').setAttribute('aria-valuetext',state.scores[current]===null?'5 из 10, пока не подтверждено':state.scores[current]+' из 10');$('step-counter').textContent=(current+1)+' из 8';$('step-dots').innerHTML=spheres.map((s,i)=>`<span class="${i===current?'active':state.scores[i]!==null?'done':''}" aria-label="${esc(s.name)}: ${i===current?'текущая':state.scores[i]!==null?'оценено':'не оценено'}"></span>`).join('');document.querySelectorAll('[data-importance]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.importance===state.importance[current])));$('back').disabled=current===0;$('next').textContent=current===7?'Моя карьерная картина →':'Дальше →';$('step-status').textContent=state.scores[current]===null?'Нажмите «Дальше», чтобы подтвердить оценку.':'Можно изменить оценку и продолжить.';draw();}
function invalidate(){report=null;demo=false;$('results').hidden=true;$('copy').hidden=true;updateGift();}
$('score').addEventListener('input',()=>{trackStudyStart();state.scores[current]=+$('score').value;$('score-output').textContent=state.scores[current]+' / 10';$('score').setAttribute('aria-valuetext',state.scores[current]+' из 10');invalidate();draw();});
document.querySelectorAll('[data-importance]').forEach(b=>b.addEventListener('click',()=>{trackStudyStart();state.importance[current]=+b.dataset.importance;invalidate();document.querySelectorAll('[data-importance]').forEach(x=>x.setAttribute('aria-pressed',String(+x.dataset.importance===state.importance[current])));draw();}));
$('back').addEventListener('click',()=>{if(current>0){current--;renderStep();$('sphere-name').focus({preventScroll:true});}});
$('next').addEventListener('click',()=>{trackStudyStart();state.scores[current]=+$('score').value;invalidate();if(current<7){current++;renderStep();$('sphere-name').focus({preventScroll:true});}else{const missing=state.scores.findIndex(v=>v===null);if(missing>=0){current=missing;renderStep();$('step-status').textContent='Оцените эту сферу, чтобы получить свою карту.';}else showResult({scores:[...state.scores],importance:[...state.importance]},false);}});
function begin(){current=Math.max(0,state.scores.findIndex(v=>v===null));renderStep();scrollToSection('assessment');}
$('start').addEventListener('click',begin);document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();begin();});document.querySelectorAll('.research-link').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();begin();}));
function exampleData(){return {scores:[7,5,3,6,6,7,5,4],importance:[3,2,3,2,2,3,2,3]};}
$('example').addEventListener('click',()=>showResult(exampleData(),true));
$('fill-example').addEventListener('click',()=>{if(state.scores.some(v=>v!==null)&&!confirm('Заменить ваши оценки демонстрационным примером?'))return;state=exampleData();analyticsExample=true;trackGoal('demo_view');invalidate();current=2;renderStep();$('step-status').textContent='Это пример. Измените оценки под свой опыт.';scrollToSection('assessment');});
function buildReport(data){const ranked=data.scores.map((v,i)=>({i,need:(10-v)*data.importance[i]})).sort((a,b)=>b.need-a.need||data.importance[b.i]-data.importance[a.i]||a.i-b.i);const focus=ranked[0].i;const support=data.scores.map((v,i)=>({i,v})).sort((a,b)=>b.v-a.v||data.importance[b.i]-data.importance[a.i]||a.i-b.i)[0];const allGood=data.scores.every(v=>v>=7);const allLow=data.scores.every(v=>v<=4);const curve=describeCurve(data.scores);const f=spheres[focus];const supportText=support.v>=6?`«${spheres[support.i].name}» — ${support.v}/10. Это одна из сильных сторон вашей карьеры, на которую можно опереться.`:`Сейчас нет сферы с высокой оценкой. Можно начать с конкретной опоры: человека, навыка или опыта, который помогает вам справляться.`;let focusText=allGood?'Вы довольны многими сторонами работы. Обязательной проблемы нет: можно сохранить подходящие условия или выбрать следующий этап.':allLow?'Несколько сфер одновременно не устраивают. Начните с одного посильного изменения, чтобы не перегружать себя.':`«${f.name}» — ${data.scores[focus]}/10, важность ${['невысокая','средняя','высокая'][data.importance[focus]-1]}. Здесь один из главных приоритетов для изменений.`;if(!allGood&&!allLow)focusText+=' '+f.why;return {focus,supportText,focusText,curve,question:allGood?'Какой следующий шаг мне интересен, если не нужно никому доказывать свой успех?':f.question,data};}
function showResult(data,isDemo,shouldScroll=true){if(isDemo)trackGoal('demo_view');else if(!analyticsExample)trackGoal('study_complete',true);report=buildReport(data);demo=isDemo;$('support-text').textContent=report.supportText;$('focus-text').textContent=report.focusText;$('result-caption').textContent=isDemo?'Пример результата на условных ответах. Ваши оценки не изменены.':'Ваши карьерные опоры и то, что требует внимания. Направление и следующие шаги обсудим на сессии.';$('results').hidden=false;$('copy').hidden=false;$('copy-status').textContent='';$('save-status').textContent='';updateGift();draw();if(shouldScroll)scrollToSection('results');}
$('edit').addEventListener('click',()=>{current=0;renderStep();scrollToSection('assessment');});
function requestText(){if(!report||demo)return 'Яна, здравствуйте! Хочу пройти мини-исследование карьерного баланса и получить диагностическую сессию в подарок.';return `Яна, здравствуйте! Я прошёл(ла) мини-исследование карьеры за последние полгода и хочу получить диагностическую сессию в подарок. Мой фокус — ${spheres[report.focus].name.toLowerCase()}: ${report.data.scores[report.focus]}/10, важность ${report.data.importance[report.focus]}/3. Подскажите, пожалуйста, доступное время.`;}
function updateGift(){const completed=!!report&&!demo&&report.data.scores.every(v=>v!==null);$('consultation').hidden=!completed;$('copy').hidden=!completed;$('gift-description').textContent='Вы завершили мини-исследование карьерного баланса. Приглашаю вас на диагностическую сессию в подарок: обсудим вашу карьерную картину, что сейчас требует внимания и с какого шага можно начать.';$('booking-link').href=window.BALANCE_CONFIG.bookingUrl;$('start').textContent='Исследовать мою карьеру →';}$('copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(requestText());$('copy-status').textContent='Запрос скопирован. Отправьте его Яне в Telegram или MAX.';}catch{$('copy-status').textContent=requestText();}});
$('save').addEventListener('click',()=>{if(!report)return;const text=['ЯНА ОЛЕНЯК · РЕФРЕЙМИНГ РЕАЛЬНОСТИ',demo?'ПРИМЕР НА УСЛОВНЫХ ОТВЕТАХ':'МОЯ КАРЬЕРНАЯ КАРТА · ПОСЛЕДНИЕ ПОЛГОДА',...spheres.map((s,i)=>`${s.name}: ${report.data.scores[i]}/10, важность ${report.data.importance[i]}/3`),'МОЯ ОПОРА',report.supportText,'ЧТО ТРЕБУЕТ ВНИМАНИЯ',report.focusText,'КОНСУЛЬТАЦИЯ',requestText(),'Telegram: '+window.BALANCE_CONFIG.bookingUrl,'MAX: '+window.BALANCE_CONFIG.maxUrl].join('\n\n');const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=demo?'primer-kariernoy-karty.txt':'moya-kariernaya-karta.txt';a.click();trackGoal(demo||analyticsExample?'demo_download':'card_download');setTimeout(()=>URL.revokeObjectURL(url),1000);$('save-status').textContent='Карта сохранена в текстовый файл.';});
function reset(){if(!confirm('Удалить ваши карьерные ответы из этого браузера?'))return;state=fresh();current=0;analyticsExample=false;invalidate();clearLegacyAnswers();renderStep();scrollToSection('assessment');}
$('reset').addEventListener('click',reset);$('clear').addEventListener('click',reset);updateGift();
if(window.BALANCE_CONFIG.photoUrl){const img=$('consultant-photo');img.addEventListener('load',()=>{img.hidden=false;$('portrait-fallback').hidden=true;});img.addEventListener('error',()=>{img.hidden=true;$('portrait-fallback').hidden=false;});img.src=window.BALANCE_CONFIG.photoUrl;}
$('sphere-name').setAttribute('tabindex','-1');renderStep();



function clearLegacyAnswers(){try{for(const key of ['career-magnet-v3','career-wheel-v2','balance-wheel-v1'])localStorage.removeItem(key);}catch{}}
function startFreshVisit(){clearLegacyAnswers();state=fresh();current=0;report=null;demo=false;analyticsExample=false;$('results').hidden=true;$('copy-status').textContent='';$('save-status').textContent='';$('support-text').textContent='';$('focus-text').textContent='';$('result-caption').textContent='';updateGift();renderStep();}
startFreshVisit();
window.addEventListener('pageshow',event=>{if(event.persisted)startFreshVisit();});
document.querySelectorAll('[data-max-contact]').forEach(link=>{link.href=window.BALANCE_CONFIG.maxUrl;});

document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(!link)return;let messenger;try{const host=new URL(link.href).hostname;if(host==='t.me')messenger='telegram';else if(host==='max.ru')messenger='max';}catch{}if(!messenger)return;trackGoal('contact_'+messenger);if(link.closest('#consultation')&&report&&!demo&&!analyticsExample)trackGoal('gift_'+messenger);});